@startuml

class Ingredient {
  +name : string
  +measuringUnit : string
  +quantityInStock : float
}

class Dish {
  +name : string
  +numericIdentifier : int
}

class Table {
  +numericIdentifier : int
  +maximumAmmountOfPeople : int
}

class Meal {
  +date : date
  +startTime : time
  +endTime : time
}

class Person {
  +name : string
  +address : string
}

class Client extends Person {
  +taxIdentificationNumber : string
}

class Waiter extends Person {
  +numericIdentifier : int
  +phoneNumber : string
}

class IngredientDish {
  +quantity : float
}

class DishMeal {
  +quantity : int
}

Ingredient "1" -- "*" IngredientDish
Dish "1" -- "*" IngredientDish
Dish "1" -- "*" DishMeal
Meal "*" -- "1" Table
Meal "*" -- "0..1" Client
Meal "*" -- "1" Waiter
Meal "*" -- "*" DishMeal

@enduml

